{"kind":"source-patchset","version":1,"disposition":"candidate","reason":"Bound distinct event scheduling before growing root or pending work collections; each root or cause is queued at most once while all semantic roots remain available for longest-path depth propagation.","changes":[{"operation":"edit","path":"src/journal/filesystem/source-owner.mjs","inputSha256":"c60d031c460557e2437b98d835c8cecfe9cd1a159f4f89cb7007ad5093417b10","replacements":[{"before":"  const roots = new Set(requestedEvents);
  const requiredArtifacts = new Set();
  const eventRecords = new Map();
  const orderedSources = new Set();","after":"  const roots = new Set();
  const requiredArtifacts = new Set();
  const eventRecords = new Map();
  const orderedSources = new Set();
  const pending = [];
  const scheduledEvents = new Set();

  function scheduleEvent(reference, isRoot = false) {
    if (!scheduledEvents.has(reference)) {
      if (scheduledEvents.size >= limits.maxClosureWitnesses) {
        throw unavailable("resource-limit", "closure-witness-count");
      }
      scheduledEvents.add(reference);
      pending.push(reference);
    }
    if (isRoot) roots.add(reference);
  }

  for (const reference of requestedEvents) scheduleEvent(reference, true);"},{"before":"    roots.add(verified.id);","after":"    scheduleEvent(verified.id, true);"},{"before":"  const pending = [...roots];
  while (pending.length > 0) {","after":"  while (pending.length > 0) {"},{"before":"    for (const cause of witness.core.causes) pending.push(cause);","after":"    for (const cause of witness.core.causes) scheduleEvent(cause);"}],"clauses":["F-S20"]}]}
